INSERT INTO training_knowledge.exercises (id,data) VALUES ('E123','{"id": "E123", "name_da": "Assisteret pull up", "category": "styrke", "movement_pattern": "vertical_pull", "required_equipment": ["maskine_assistedchin"], "level": "let_oevet", "instruction_da": "Tilpas hjælpen og støtten. Træk kroppen op og sænk kontrolleret. Mere modvægt giver normalt mere hjælp.", "source_ids": ["S25", "S31"], "provenance": "original_coaching_description_machine_catalogue_reference", "review_status": "needs_coach_review", "medical_clearance_claim": false, "default_sets": null, "default_reps": null, "default_load_kg": null, "media": null, "media_license": null, "notes": "Indstilling og egnethed kræver trænerens gennemgang. Belastning kan ikke omregnes direkte mellem mærker og modeller.", "machine_references": [{"brand": "BH Fitness / MOVEMIA", "series": "MOVEMIA", "model": "M450 Assisted Chin and Dip", "source_id": "S25", "url": "https://bh.fitness/en/equipments/strength/movemia-strength/", "match_status": "catalogue_movement_example_verify_local_setup", "checked_at": "2026-11-03"}, {"brand": "Life Fitness", "series": "Insignia", "model": "Assist Dip Chin", "source_id": "S31", "url": "https://www.lifefitness.com/en-us/catalog/strength-training/selectorized/insignia-series", "match_status": "catalogue_movement_example_verify_local_setup", "checked_at": "2026-11-03"}]}'::jsonb) ON CONFLICT (id) DO NOTHING;
